"""
フラット多次元配列 & ビットセット (Flat Multi-dimensional Array & Bitset)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- Flat2D(h, w, val=0):
  1次元リスト [val] * (h * w) で2次元配列を高速に管理。
  grid[r, c] でアクセス可能。
- FlatND(dims, val=0):
  任意の多次元配列 dims=(d0, d1, ...) を1次元配列で管理。
  arr[i0, i1, ...] でアクセス可能。
- Bitset: Pythonの多倍長整数 int を用いた O(N/64) ビット並列化。
"""

# https://github.com/ddfkit/acsampl/blob/main/high_array.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class Flat2D:
    def __init__(self,h,w,v=0):self.h,self.w,self.d=h,w,[v]*(h*w)
    def __getitem__(self,idx):r,c=idx;return self.d[r*self.w+c]
    def __setitem__(self,idx,v):r,c=idx;self.d[r*self.w+c]=v

# https://github.com/ddfkit/acsampl/blob/main/high_array.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class FlatND:
    def __init__(self,dims,v=0):
        self.dims=dims;m=1;self.stride=[]
        for d in reversed(dims):self.stride.append(m);m*=d
        self.stride=self.stride[::-1];self.d=[v]*m
    def __getitem__(self,idx):
        p=sum(i*s for i,s in zip(idx,self.stride));return self.d[p]
    def __setitem__(self,idx,v):
        p=sum(i*s for i,s in zip(idx,self.stride));self.d[p]=v

if __name__ == "__main__":
    f2 = Flat2D(3, 4, 0)
    f2[1, 2] = 42
    assert f2[1, 2] == 42 and f2[0, 0] == 0

    f3 = FlatND((2, 3, 4), -1)
    f3[1, 2, 3] = 99
    assert f3[1, 2, 3] == 99 and f3[0, 0, 0] == -1

    bs = 1
    for x in [2, 3, 5]: bs |= (bs << x)
    assert (bs >> 8) & 1
    assert not ((bs >> 6) & 1)
    print("high_array.py: tests passed!")
